let NAME_REGEX=/^\w{2,}(\s\w{2,})?\s\w{2,}$/i,LETTERS_ONLY=/^[a-z ]+$/i,SPACE_REGEX=/^[\S]+(\s+[^\s]+)*$/i,EMAIL_REGEX=/^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/i;$().ready(function(){$("#subscribe-form").validate({rules:{EMAIL:{required:!0,email:!0}},messages:{EMAIL:{required:"This Field is Required",email:"Plase Enter Valid Email Address"}}}),$("#contact-form").validate({rules:{fullname:{required:!0,validName:!0,lettersOnly:!0,noSpace:!0},email:{required:!0,email:!0},mobile:{required:!0,number:!0,minlength:7,maxlength:16},company:{required:!0,noSpace:!0},message:{required:!0,minlength:20}},messages:{fullname:{required:"This Field is Required",validName:"Please Enter Valid Name",lettersOnly:"Please Enter Only Alphabets",noSpace:"Please Remove Unnecessary white-spaces"},email:{required:"This Field is Required",email:"Please Enter Valid Email Address"},mobile:{required:"This Field is Required",number:"Please Enter Numbers Only",minlength:"Please Enter Valid Mobile Number",maxlength:"Please Enter Valid Mobile Number"},company:{required:"This Field is Required",noSpace:"Please Remove Unnecessary white-spaces"},message:{required:"This Field is Required",minlength:"Minimum 20 Characters Required"}}}),$("#supplier-form-modal").validate({rules:{fullname:{required:!0,validName:!0,lettersOnly:!0,noSpace:!0},email:{required:!0,email:!0},mobile:{required:!0,number:!0,minlength:7,maxlength:16},company:{required:!0,noSpace:!0},message:{required:!0,minlength:20},AdharCardNumber:{required:!0},ProductsAvailable:{required:!0},RegistrationNumber:{required:!0}},messages:{fullname:{required:"This Field is Required",validName:"Please Enter Valid Name",lettersOnly:"Please Enter Only Alphabets",noSpace:"Please Remove Unnecessary white-spaces"},email:{required:"This Field is Required",email:"Please Enter Valid Email Address"},mobile:{required:"This Field is Required",number:"Please Enter Numbers Only",minlength:"Please Enter Valid Mobile Number",maxlength:"Please Enter Valid Mobile Number"},company:{required:"This Field is Required",noSpace:"Please Remove Unnecessary white-spaces"},message:{required:"This Field is Required",minlength:"Minimum 20 Characters Required"},AdharCardNumber:{required:"This Field is Required"},ProductsAvailable:{required:"This Field is Required"},RegistrationNumber:{required:"This Field is Required"}}}),jQuery.validator.addMethod("validName",function(e,i){return this.optional(i)||NAME_REGEX.test(e)}),jQuery.validator.addMethod("lettersOnly",function(e,i){return this.optional(i)||LETTERS_ONLY.test(e)}),jQuery.validator.addMethod("noSpace",function(e,i){return this.optional(i)||SPACE_REGEX.test(e)}),jQuery.validator.addMethod("email",function(e,i){return this.optional(i)||EMAIL_REGEX.test(e)})});